// Reads node 1 and builds one Actor input per repository. Edit node 1, not this code.
const s = $input.first().json;
const number = (value, fallback) => { const n = Number(value); return Number.isFinite(n) ? n : fallback; };
const clamp = (value, min, max, fallback) => Math.min(max, Math.max(min, number(value, fallback)));
const list = (value) => String(value ?? '').split(/[,\n]/).map((part) => part.trim()).filter(Boolean);
const repositories = [];
for (const raw of list(s.repositories)) {
  const match = /^(?:https?:\/\/)?(?:www\.)?(?:github\.com\/)?([A-Za-z0-9-]+)\/([A-Za-z0-9._-]+?)(?:\.git)?\/?$/.exec(raw);
  if (!match) throw new Error('"' + raw + '" in "repositories" (node 1) is not a public GitHub repository. Use owner/name, for example axios/axios.');
  const repository = (match[1] + '/' + match[2]).toLowerCase();
  if (!repositories.includes(repository)) repositories.push(repository);
}
if (!repositories.length) throw new Error('Add at least one repository to "repositories" in node 1, for example axios/axios.');
if (repositories.length > 10) throw new Error('Watch at most 10 repositories per run; node 1 has ' + repositories.length + '.');
const state = ['open', 'closed', 'all'].includes(String(s.state ?? '').trim()) ? String(s.state).trim() : 'open';
const lookbackDays = Math.round(clamp(s.lookbackDays, 1, 90, 7));
const since = new Date(Date.now() - lookbackDays * 86400000).toISOString().slice(0, 10);
const labels = list(s.labels).slice(0, 20);
const token = String(s.githubToken ?? '').trim();
const maxCostUsd = clamp(s.maxCostUsdPerRepository, 0.01, 0.5, 0.05);
return repositories.map((repository) => ({
  json: {
    repository,
    maxCostUsd,
    actorInput: {
      repositories: [repository],
      state,
      includeIssues: true,
      includePullRequests: s.includePullRequests === true || String(s.includePullRequests).toLowerCase() === 'true',
      since,
      maxItems: Math.round(clamp(s.maxIssuesPerRepository, 1, 50, 10)),
      ...(labels.length ? { labels } : {}),
      ...(token ? { githubToken: token } : {})
    }
  }
}));

// The Apify node continues on error so one bad repository does not stop the others.
// If no repository run succeeded (for example the Apify credential is missing), stop here before any read or write.
const items = $input.all();
const errors = items.map((item) => item.json ?? {}).filter((json) => json.error !== undefined && !json.url);
const succeeded = items.some((item) => item.json && item.json.url);
if (errors.length && !succeeded && errors.length >= $('Build One Actor Input per Repository').all().length) {
  const first = errors[0].error;
  const message = typeof first === 'string' ? first : (first?.message ?? errors[0].message ?? 'unknown error');
  throw new Error('Every Apify run failed, so nothing was read or written. First error: ' + String(message).slice(0, 300));
}
return items;

// Keeps issues that are new to the sheet or were updated since they were logged.
const settings = $('1. Set your watched repositories').first().json;
const inputs = $('Build One Actor Input per Repository').all().map((item) => item.json.repository);
const number = (value, fallback) => { const n = Number(value); return Number.isFinite(n) ? n : fallback; };
const maxToScore = Math.min(50, Math.max(1, Math.round(number(settings.maxIssuesToScorePerRun, 30))));

// The Apify node continues on error, so one bad repository does not stop the others.
const apifyItems = $('2. Fetch Issues with Apify').all();
const failed = [];
const rows = [];
apifyItems.forEach((item, index) => {
  const json = item.json ?? {};
  if (json.error !== undefined && !json.url) {
    const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
    const at = Number.isInteger(paired?.item) ? paired.item : index;
    const message = typeof json.error === 'string' ? json.error : (json.error?.message ?? json.message ?? 'unknown error');
    failed.push({ repository: inputs[at] ?? 'a repository', message: String(message).slice(0, 300) });
  } else if (json.url && json.number !== undefined) rows.push(json);
});
const failedRepos = [...new Set(failed.map((entry) => entry.repository))];

const time = (value) => { const t = Date.parse(String(value ?? '')); return Number.isFinite(t) ? t : null; };
const logged = new Map();
for (const item of $input.all()) {
  const url = String(item.json.url ?? '').trim();
  if (url) logged.set(url, { updatedAt: time(item.json.updatedAt), alerted: String(item.json.alerted ?? '').trim().toLowerCase() === 'yes' });
}

const seen = new Set();
let unchanged = 0;
const fresh = [];
for (const row of rows) {
  if (seen.has(row.url)) continue;
  seen.add(row.url);
  const before = logged.get(row.url);
  if (before && before.updatedAt !== null && before.updatedAt === time(row.updatedAt)) { unchanged += 1; continue; }
  fresh.push({ row, before });
}
fresh.sort((a, b) => (time(b.row.updatedAt) ?? 0) - (time(a.row.updatedAt) ?? 0));
const picked = fresh.slice(0, maxToScore);
const issues = picked.map(({ row, before }, index) => ({
  ref: index + 1,
  repository: row.repository ?? row.sourceRepository ?? '',
  type: row.type === 'pull_request' ? 'pull request' : 'issue',
  number: row.number,
  title: String(row.title ?? ''),
  url: row.url,
  authorLogin: row.authorLogin ?? '',
  labels: Array.isArray(row.labels) ? row.labels.map(String) : [],
  commentsCount: Number.isFinite(row.commentsCount) ? row.commentsCount : 0,
  reactions: Number.isFinite(row.reactions?.total) ? row.reactions.total : 0,
  createdAt: row.createdAt ?? '',
  updatedAt: row.updatedAt ?? '',
  bodyExcerpt: String(row.bodyExcerpt ?? '').replace(/\s+/g, ' ').trim().slice(0, 800),
  previouslyAlerted: before?.alerted === true,
  previouslyLogged: Boolean(before)
}));

const summary = {
  repositories: inputs.length,
  failedRepositories: failed.map((entry) => entry.repository + ': ' + entry.message),
  returned: rows.length,
  unchanged,
  heldForNextRun: Math.max(0, fresh.length - picked.length),
  toScore: issues.length
};
let message;
if (issues.length) message = issues.length + ' new or updated issues to score.';
else if (!rows.length) message = 'No issues were updated in the lookback window for these repositories' + (failed.length ? ' (' + failedRepos.length + ' repositories failed: ' + failedRepos.join(', ') + ')' : '') + '. Nothing was written to Google Sheets or Slack.';
else message = 'No new or updated issues: all ' + unchanged + ' returned issues are already in the sheet unchanged. Nothing was written to Google Sheets or Slack.';
return [{ json: { hasIssues: issues.length > 0, message, summary, issues } }];

// Checks the OpenAI answer before anything is written. A bad answer stops the run with no writes.
const CATEGORIES = ['bug', 'regression', 'security', 'breaking-change', 'feature', 'question'];
function parseStructured(root) {
  const seen = new Set();
  function visit(value) {
    if (value === null || value === undefined) return null;
    if (typeof value === 'string') {
      const text = value.trim().replace(/^\x60\x60\x60(?:json)?\s*/i, '').replace(/\s*\x60\x60\x60$/, '');
      if (!text.startsWith('{')) return null;
      try { return visit(JSON.parse(text)); } catch { return null; }
    }
    if (typeof value !== 'object' || seen.has(value)) return null;
    seen.add(value);
    if (Array.isArray(value.scores)) return value;
    for (const nested of Array.isArray(value) ? value : Object.values(value)) {
      const found = visit(nested);
      if (found) return found;
    }
    return null;
  }
  return visit(root);
}
const picked = $('Pick New or Updated Issues').first().json;
const settings = $('1. Set your watched repositories').first().json;
const threshold = Math.min(5, Math.max(1, Math.round(Number(settings.alertMinRiskScore) || 4)));
const byRef = new Map(picked.issues.map((issue) => [issue.ref, issue]));
const reject = (reason) => [{ json: { valid: false, message: 'OpenAI scores were rejected (' + reason + '). Nothing was written to Google Sheets or Slack; run the workflow again.' } }];
const parsed = parseStructured($input.first().json);
if (!parsed) return reject('no JSON with a "scores" list');

const scored = new Map();
for (const entry of parsed.scores) {
  const ref = Number(entry?.ref);
  const riskScore = Number(entry?.riskScore);
  const category = String(entry?.category ?? '').trim().toLowerCase();
  const affectsUpgrade = String(entry?.affectsUpgrade ?? '').trim().toLowerCase();
  const summary = String(entry?.summary ?? '').replace(/\s+/g, ' ').trim();
  if (!byRef.has(ref) || scored.has(ref)) continue;
  if (!Number.isInteger(riskScore) || riskScore < 1 || riskScore > 5) continue;
  if (!CATEGORIES.includes(category) || !['yes', 'no'].includes(affectsUpgrade) || !summary) continue;
  scored.set(ref, { riskScore, category, affectsUpgrade, summary: summary.slice(0, 300) });
}
if (!scored.size) return reject('no valid score for an issue from this run');

const scrapedAt = $now.toUTC().toISO();
return picked.issues.filter((issue) => scored.has(issue.ref)).map((issue) => {
  const score = scored.get(issue.ref);
  const alertNow = score.riskScore >= threshold && !issue.previouslyAlerted;
  return {
    json: {
      valid: true,
      alertNow,
      type: issue.type,
      scrapedAt,
      repository: issue.repository,
      number: issue.number,
      title: issue.title,
      url: issue.url,
      authorLogin: issue.authorLogin,
      labels: issue.labels.join(', '),
      commentsCount: issue.commentsCount,
      reactions: issue.reactions,
      createdAt: issue.createdAt,
      updatedAt: issue.updatedAt,
      category: score.category,
      riskScore: score.riskScore,
      affectsUpgrade: score.affectsUpgrade,
      summary: score.summary,
      alerted: alertNow || issue.previouslyAlerted ? 'yes' : 'no'
    }
  };
});

// Builds one Slack message after the sheet write succeeded. A quiet day posts nothing.
const rows = $('Check Scores and Build Sheet Rows').all().map((item) => item.json);
const summary = $('Pick New or Updated Issues').first().json.summary;
const settings = $('1. Set your watched repositories').first().json;
const threshold = Math.min(5, Math.max(1, Math.round(Number(settings.alertMinRiskScore) || 4)));
const alerts = rows.filter((row) => row.alertNow).sort((a, b) => b.riskScore - a.riskScore || String(b.updatedAt).localeCompare(String(a.updatedAt)));
const notScored = summary.toScore - rows.length;
if (!alerts.length) {
  return [{ json: { hasAlerts: false, message: rows.length + ' issues logged to Google Sheets; none scored ' + threshold + ' or higher for the first time, so no Slack message was sent.' } }];
}
const clean = (text) => String(text ?? '').replace(/[<>|*_~\x60]/g, ' ').replace(/\s+/g, ' ').trim();
const lines = ['*Dependency risk: ' + alerts.length + ' high-risk ' + (alerts.length === 1 ? 'item' : 'items') + '* (risk ' + threshold + '+ of 5)'];
for (const repository of [...new Set(alerts.map((row) => row.repository))]) {
  lines.push('', '*' + clean(repository) + '*');
  for (const row of alerts.filter((entry) => entry.repository === repository)) {
    const upgrade = row.affectsUpgrade === 'yes' ? ', affects upgrades' : '';
    lines.push('• <' + row.url + '|#' + row.number + ' ' + clean(row.title).slice(0, 90) + '>: risk ' + row.riskScore + ', ' + row.category + upgrade + '. ' + clean(row.summary));
  }
}
const notes = [rows.length + ' issues scored and logged'];
if (summary.unchanged) notes.push(summary.unchanged + ' unchanged since the last run');
if (summary.heldForNextRun) notes.push(summary.heldForNextRun + ' held for the next run by maxIssuesToScorePerRun');
if (notScored > 0) notes.push(notScored + ' not scored by the AI, retried next run');
lines.push('', '_' + notes.join('; ') + '._');
if (summary.failedRepositories.length) lines.push('_Failed repositories: ' + clean(summary.failedRepositories.join('; ')).slice(0, 500) + '._');
return [{ json: { hasAlerts: true, text: lines.join('\n') } }];
